public sealed class RecordingShipper : IShipper
{
    private readonly string _label;

    public RecordingShipper(string label)
    {
        _label = label;
    }

    public string Name => "RecordingShipper";
    public List<string> References { get; } = new();
    public List<string> Services { get; } = new();

    public string CreateLabel(string reference, string service)
    {
        References.Add(reference);
        Services.Add(service);
